        ownerId: getOwnerId(),
        viewMode: viewModeRef.current,
        currentlyRenderedCards: Array.isArray(usersRef.current) ? usersRef.current.length : 0,
        currentlyLoadedIds: loadedIdsRef.current?.size || 0,
        hasMore: Boolean(res?.hasMore),
